//! 🧪️ Concrete byte pops and physical releases retain their actual CPU through natural retirement.
use super::*;
use crate::observe_retirement_allocations as heap;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
struct Bank{work:u64,copy:usize,capacity:usize,release:usize,actual:Option<usize>,bank:EffectBank,last:RetainedCloneGrant}
impl Bank{
 fn new(law:&serde_json::Value)->Self{let s=&law["stock"];let work=s["work"].as_u64().unwrap();let copy=s["copy"].as_u64().unwrap()as usize;let capacity=s["capacity"].as_u64().unwrap()as usize;let release=s["release"].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:copy,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:s["depth"].as_u64().unwrap()as usize};Self{work,copy,capacity,release,actual:None,bank:EffectBank::new(Wallet::new(grant,work)),last:Default::default()}}
 fn effect<R>(&mut self,grant:RetainedCloneGrant,run:impl FnOnce(&mut crate::RetainedAllocationEffect<'_>)->R)->R{assert!(self.actual.is_none());let mut output=None;let mut run=Some(run);let(poll,actual)=self.bank.run(grant,self.work,|effect|{let boundary=effect.performed_boundary();output=Some(run.take().unwrap()(effect));crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(boundary).unwrap()})});assert!(matches!(poll,crate::RetainedWorkPoll::Complete(_)));self.actual=actual;self.last=grant;assert!(matches!(self.bank.take_admitted(),None|Some(true)));output.unwrap()}
 fn debit(&mut self,w:u128,p:RetainedCloneProgress,h:(usize,usize)){assert!(w<=u128::from(self.work)&&p.copied_bytes<=self.copy&&p.retained_capacity_bytes<=self.capacity&&p.released_bytes<=self.release);assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));self.work-=u64::try_from(w).unwrap();self.copy-=p.copied_bytes;self.capacity-=p.retained_capacity_bytes;self.release-=p.released_bytes;assert_eq!(self.bank.wallet().remaining_work(),self.work);self.bank.post(p,self.last,h)}
}
/// 🎯️ Settles the copy body a step quotes with on the copy body its own grant names.
fn quoted(body:usize,next:impl Fn(usize)->crate::RetirementDemand)->(usize,crate::RetirementDemand){let mut copy=body;for _ in 0..8{let d=next(copy);let want=body.max(d.copy_bytes);if want==copy{return(copy,d)}copy=want}panic!("paged quote did not settle on one copy body")}
fn law()->serde_json::Value{let law:serde_json::Value=serde_json::from_str(include_str!("close-work.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("close-work.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v)}law}
fn text(length:usize,byte:u8,bank:&mut Bank)->PagedText<4097>{let mut owner=PagedText::empty();while owner.bytes.capacity()<length{let n=owner.bytes.next_exact_capacity_allocation_bytes(length).unwrap().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:owner.bytes.next_capacity_copy_byte_demand(length).unwrap(),maximum_capacity_bytes:n,maximum_depth:owner.bytes.next_capacity_depth_demand(length).unwrap(),..Default::default()};let(turn,h)=heap(||bank.effect(g,|effect|owner.bytes.reserve_exact_capacity_one(length,effect)));let w=turn.work;let crate::list::PagedListReservationOutcome::Ready(p)=turn.result.unwrap()else{panic!("quoted text page denied")};assert_eq!(bank.actual.take(),Some(p.allocated_bytes));bank.debit(w,RetainedCloneProgress{copied_items:1,copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes},h);}for _ in 0..length{let mut value=Some(byte);let d=owner.bytes.adoption_demand(&value).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};let(turn,h)=heap(||bank.effect(g,|effect|owner.bytes.adopt_reserved(&mut value,effect)));let w=turn.work;let p=turn.result.unwrap();assert!(value.is_none());bank.debit(w,RetainedCloneProgress{copied_items:1,copied_bytes:p.placed_bytes,..Default::default()},h);}owner}
#[test]
fn paged_text_close_returns_actual_byte_and_release_work_from_one_finite_bank(){
 let law=law();for length in law["lengths"].as_array().unwrap(){let length=length.as_u64().unwrap()as usize;for body in law["copyBodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for items in law["itemOffers"].as_array().unwrap(){let items=items.as_u64().unwrap()as usize;let mut bank=Bank::new(&law);let mut owner=text(length,law["byte"].as_u64().unwrap()as u8,&mut bank);let actual:Vec<u8>=owner.bytes.iter().copied().collect();assert_eq!(serde_json::to_value(&actual).unwrap(),serde_json::json!(vec![120u8;length]));
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(copy,d)=quoted(body,|b|owner.next_demand(b).unwrap());let g=RetainedCloneGrant{maximum_items:items.min(bank.work as usize),maximum_copy_bytes:copy.min(bank.copy),maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..Default::default()};let before=(owner.bytes.len(),owner.allocated_bytes(),owner.bytes.backing_ptr(0));
   let denied=[Some(RetainedCloneGrant{maximum_items:0,..g}),d.copy_bytes.checked_sub(1).map(|maximum_copy_bytes|RetainedCloneGrant{maximum_copy_bytes,..g}),d.release_bytes.checked_sub(1).map(|maximum_release_bytes|RetainedCloneGrant{maximum_release_bytes,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g})];
   for denied in denied.into_iter().flatten(){let(result,h)=heap(||bank.effect(denied,|effect|owner.close_retained(effect)));assert_eq!(result.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(h,(0,0));match result.result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>{assert_eq!(denied.maximum_depth,0);assert_eq!(error.retained_progress(),Default::default())}}assert_eq!((owner.bytes.len(),owner.allocated_bytes(),owner.bytes.backing_ptr(0)),before);}
   let(result,h)=heap(||bank.effect(g,|effect|owner.close_retained(effect)));let w=result.work;let p=result.result.unwrap().progress();assert!(w<=g.maximum_items as u128);assert!(p.fits(g));let removed=before.0-owner.bytes.len();if removed>0{assert_eq!(w,removed as u128);assert_eq!(p.copied_bytes,removed+2*size_of::<usize>())}bank.debit(w,p,h);assert!(turn<16383);
  }
  assert!(owner.terminal_is_empty());let cached=bank.effect(Default::default(),|effect|owner.close_retained(effect));assert_eq!(cached.work,u128::from(law["cachedWork"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),Default::default());assert_eq!(heap(||drop(owner)).1,(0,0));
 }}}
}

struct NaturalClose;
impl crate::OriginalEffectProducer for NaturalClose{
 type Output=crate::retirement::RetirementStep;type Failure=crate::OriginalRetirementFailure;type Context<'a,'b>=(usize,&'a mut PagedTextRetirement<4097>) where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:crate::OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<crate::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{crate::retirement::RetirementCursor::close_into(c.1,c.0,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut crate::RetainedAllocationEffect<'_>,r:crate::OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<crate::OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{crate::retirement::RetirementCursor::recover_close_into(c.1,c.0,e,r)}
}
fn natural_step(owner:&mut PagedTextRetirement<4097>,body:usize,authority:&mut crate::OriginalEffectAuthority<NaturalClose>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::retirement::RetirementStep{let(mut action,mut reply)=(None,None);assert!(authority.drive(&mut (body,&mut *owner),effect,&mut action).unwrap());assert!(action.as_mut().unwrap().transfer_reply(&mut reply).unwrap());authority.finish(&mut action).unwrap();reply.unwrap().unwrap()}
#[test]
fn paged_text_natural_wrapper_forwards_direct_work_before_result_matching(){
 use crate::retirement::RetirementCursor;
 let law=law();let mut bank=Bank::new(&law);let mut owner=PagedTextRetirement{owner:text(7,120,&mut bank)};let mut authority=crate::OriginalEffectAuthority::new(NaturalClose);
 let d=owner.next_demand(7).unwrap();let g=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};let(step,h)=heap(||bank.effect(g,|effect|natural_step(&mut owner,7,&mut authority,effect)));let w=step.work();match step{crate::retirement::RetirementStep::Progress(p,_)=>bank.debit(w,p,h),_=>panic!("natural close start was discarded")}
 let mut payload_work=0;for _ in 0..law["naturalFirstPayloadWork"].as_u64().unwrap(){let d=owner.next_demand(7).unwrap();let g=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};let(step,h)=heap(||bank.effect(g,|effect|natural_step(&mut owner,7,&mut authority,effect)));let w=step.work();payload_work+=w;match step{crate::retirement::RetirementStep::Progress(p,_)=>{assert_eq!(p.copied_items,1);bank.debit(w,p,h)},_=>panic!("natural byte progress was discarded")}}assert_eq!(payload_work,u128::from(law["naturalFirstPayloadWork"].as_u64().unwrap()));
 for _ in 0..16384{if owner.terminal_is_empty(){break}let d=owner.next_demand(3).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..Default::default()};let(step,h)=heap(||bank.effect(g,|effect|natural_step(&mut owner,3,&mut authority,effect)));let w=step.work();match step{crate::retirement::RetirementStep::Progress(p,_)=>bank.debit(w,p,h),crate::retirement::RetirementStep::Complete(_)=>bank.debit(w,Default::default(),h),_=>panic!("unexpected natural cursor result")}}assert!(owner.terminal_is_empty());assert!(authority.into_producer().is_ok());
}
#[test]
fn original_formatter_fragments_match_independent_unicode_and_extent_fixture(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../📋️list/🧪️tests/🧫️fixtures/🏷️formatted-exact-extent.json")).unwrap();let body="x".repeat(law["payloadBytes"].as_u64().unwrap()as usize);
 for(prefix,suffix,key)in[("Set label to ","","expectedEnBytes"),("Beschriftung auf "," setzen","expectedDeBytes")]{let formatter=FormatterRead{prefix,body:&body,suffix,body_len:body.len(),total:prefix.len()+body.len()+suffix.len()};let bytes=(0..formatter.byte_len()).map(|index|formatter.byte_at(index).unwrap()).collect::<Vec<_>>();assert_eq!(bytes.len(),law[key].as_u64().unwrap()as usize);assert_eq!(bytes,format!("{prefix}{body}{suffix}").into_bytes());assert!(formatter.byte_at(bytes.len()).is_none());}
}
